<script lang="ts">
 import CategoryPill from './CategoryPill.svelte';
 import {categoryIdentity} from '$lib/categoryIdentity';
 import type {productInsights} from '$lib/server/productInsights';
 import Title from './Title.svelte';import PeriodPicker from './PeriodPicker.svelte';import ContributionList from './ContributionList.svelte';import ReflectTabs from './ReflectTabs.svelte';import Badge from './FinancialBadge.svelte';import {formatMoney,monthLabel} from '$lib/utils';
 let {data}:{data:ReturnType<typeof productInsights>}=$props();
 const income=$derived(data.type==='income'),title=$derived(income?'Income':'Spending'),path=$derived(income?'/income':'/spending');
 const total=$derived(income?data.summary.incomeCents:data.summary.spendingCents);
 const query=$derived(data.scopeQuery??data.period.query);
 const accountQuery=$derived(data.accountId?`&account=${data.accountId}`:'');
 const scope=$derived(data.accounts.find(a=>a.id===data.accountId)?.name??'All accounts');
 const periodText=$derived(data.period.custom?`${data.period.from} – ${data.period.dateTo}`:monthLabel(data.period.month));
 const maxCategory=$derived(Math.max(1,...data.categoryRows.map(c=>Math.abs(c.cents))));
 const maxHistory=$derived(Math.max(1,...data.history.map(h=>Math.abs(h.cents))));
 function tone(cents:number):'positive'|'negative'|'neutral'{return income?(cents<0?'negative':cents>0?'positive':'neutral'):(cents<0?'positive':'neutral');}
 function state(cents:number){return income?(cents<0?'Net reversal':'Posted income'):(cents<0?'Net refunds':'After refunds');}
</script>
<Title {title}/><div class="product-page"><header class="product-heading insights-heading"><div><h1>{title}</h1><p>{income?'Recorded earnings, without counting money moved between accounts.':'Recorded spending, with refunds put back in their categories.'}</p></div><a class="product-button" href={`/transactions?date_from=${data.period.from}&date_to=${data.period.dateTo}&status=posted${accountQuery}`}>Open activity</a></header>
<PeriodPicker month={data.period.month} {path} accountId={data.accountId}/><ReflectTabs {query} current={income?'income':'spending'}/><p class="product-scope">{periodText} · {scope} · posted activity</p>
{#if data.summary.uncategorizedCount}<aside class="product-attention"><Badge label={`${data.summary.uncategorizedCount} to review`} tone="attention"/><span>Uncategorized activity is not included in this total.</span><a class="product-link" href={`/transactions?empty=category&date_from=${data.period.from}&date_to=${data.period.dateTo}&status=posted${accountQuery}`}>Review</a></aside>{/if}
<section class="product-panel"><header class="product-panel-header"><div><h2>{income?'Posted income':'Net spending'}</h2><p class="product-row-caption">{data.categoryRows.length} categories · open a figure to see its contributions</p></div><Badge value={formatMoney(total)} label={state(total)} tone={tone(total)}/></header><footer class="product-details">{data.summary.pendingCount} pending records excluded. Recorded totals are not available cash or a guarantee of complete history.</footer></section>
<div class="product-columns"><section class="product-panel"><header class="product-panel-header"><h2>{income?'Where income came from':'Spending by category'}</h2></header>{#if data.categoryRows.length}<div class="product-panel-body"><ul class="product-bars">{#each data.categoryRows as c}{@const value=income?c.cents:-c.cents}<li><a href={`/categories/${c.id}?${query}`}><div class="product-report-line"><CategoryPill id={c.id} name={c.name} color={data.categories.find(v=>v.id===c.id)?.color}/><Badge value={formatMoney(value)} label={state(value)} tone={tone(value)}/></div><div class="product-bar-track" aria-hidden="true"><div class="product-bar-fill" style:width={`${Math.abs(c.cents)/maxCategory*100}%`} style:background={categoryIdentity(c.id,data.categories.find(v=>v.id===c.id)?.color).fill}></div></div></a></li>{/each}</ul></div>{:else}<div class="product-empty"><strong>No categorized {title.toLowerCase()} yet</strong><p>Review activity or choose another month.</p><a class="product-link" href={`/transactions?date_from=${data.period.from}&date_to=${data.period.dateTo}${accountQuery}`}>Review activity</a></div>{/if}</section>
<section class="product-panel"><header class="product-panel-header"><div><h2>Six-month view</h2><p class="product-row-caption">Full months through {monthLabel(data.period.dateTo)} · {scope}</p></div></header><div class="product-panel-body"><ul class="product-bars">{#each data.history as h}<li><a href={`${path}?month=${h.month}${accountQuery}`}><div class="product-report-line"><strong>{monthLabel(`${h.month}-01`)}</strong><Badge value={h.postedCount?formatMoney(h.cents):undefined} label={h.postedCount?state(h.cents):'No posted activity'} tone={h.postedCount?tone(h.cents):'neutral'}/></div>{#if h.postedCount}<div class="product-bar-track" aria-hidden="true"><div class="product-bar-fill" style:width={`${Math.abs(h.cents)/maxHistory*100}%`} style:background={income?(h.cents<0?'var(--destructive)':'var(--success)'):'var(--muted-foreground)'}></div></div>{/if}{#if h.uncategorizedCount}<span class="product-row-caption">Some activity still needs a category</span>{/if}</a></li>{/each}</ul></div><footer class="product-details">Full calendar months, not just the custom summary range. Missing activity is not proof of no spending.</footer></section></div>
<section class="product-panel"><header class="product-panel-header"><h2>Activity behind this total</h2></header><ContributionList rows={data.contributions} expense={!income} kind={data.type}/></section>
<details class="product-panel product-details"><summary>What is included?</summary><p>{income?'Posted transactions in income categories, less income reversals. Transfers, card payments, refunds and unclassified deposits are not earnings.':'Posted transactions in expense categories, less refunds in those categories. Transfers, card payments and unclassified activity are excluded. A negative total means net refunds.'} Splits contribute only their matching portions. Pending records and forecast wages do not enter these totals.</p></details></div>
